namespace ks{namespace{PartRefreshPartialTest partialTest=nullptr;using T=PartRefreshTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::ReadCurrent:return{0xa12c,6};case S::RetainCurrent:return{0xa132,2};case S::FirstAddress:return{0xa134,4};case S::FirstIndex:return{0xa138,2};case S::SetCount:return{0xa13a,2};case S::HoldIndex:return{0xa13c,2};case S::HoldAddress:return{0xa13e,2};case S::DispatchStatus:return{0xa140,4};case S::CompareStatus:return{0xa144,2};case S::AdmitStatus:return{0xa146,2};case S::RestoreForClear:return{0xa148,2};case S::HoldForClear:return{0xa14a,2};case S::ClearValue:return{0xa14c,2};case S::DispatchClear:return{0xa14e,4};case S::RestoreForRefresh:return{0xa152,2};case S::RestoreIndexForRefresh:return{0xa154,2};case S::HoldIndexForRefresh:return{0xa156,2};case S::HoldAddressForRefresh:return{0xa158,2};case S::ReadBase:return{0xa15a,6};case S::ResolvePart:return{0xa160,2};case S::WritePart:return{0xa162,6};case S::DispatchGlobal:return{0xa168,4};case S::RestoreAddress:return{0xa16c,2};case S::RestoreIndex:return{0xa16e,2};case S::NextAddress:return{0xa170,2};case S::NextIndex:return{0xa172,2};case S::CountDown:return{0xa174,2};case S::AdmitNext:return{0xa176,2};case S::RestoreCurrent:return{0xa178,2};case S::WriteCurrent:return{0xa17a,6};case S::Finish:return{0xa180,2};case S::AwaitStatus:return{0xa144,2};case S::AwaitClear:return{0xa152,2};case S::AwaitGlobal:return{0xa16c,2}; default:throw std::runtime_error("Invalid part refresh stage");}}}
bool PartRefreshCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0xa12c){if(selected)throw std::runtime_error("Overlapping part refresh");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Part refresh capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto&v=h.regs;if(t.child()!=T::Child::None)t.resumeChild(uint8_t(v[0].rl));auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto cost=t.nextClocks();t.advanceBefore(cost,[&](T::Read r){return uint8_t(h.read8(r==T::Read::Current?0x17526:0x167ba));},[&](uint8_t value){f.store8(0x17526,int8_t(value));});auto hold=[&](auto value){f.push(value);(**selected).depth+=sizeof(value);};auto restore=[&](auto&value){f.pop(value);(**selected).depth-=sizeof(value);};switch(stage){case S::ReadCurrent:f.move(v[0].rl,t.current());break;case S::RetainCurrent:case S::HoldIndex:case S::HoldIndexForRefresh:hold(v[0].r);break;case S::FirstAddress:f.move(v[4].r,0x8041);break;case S::FirstIndex:f.move(v[0].rl,0);break;case S::SetCount:f.move(v[0].rh,4);break;case S::HoldAddress:case S::HoldForClear:case S::HoldAddressForRefresh:hold(v[4].r);break;case S::DispatchStatus:case S::DispatchClear:case S::DispatchGlobal:if(stage!=S::DispatchGlobal&&uint16_t(v[4].r)!=t.address())throw std::runtime_error("Part refresh address differs");if(stage==S::DispatchClear&&v[1].er!=0)throw std::runtime_error("Part refresh clear differs");f.call(stage==S::DispatchStatus?0x2568:stage==S::DispatchClear?0x24c6:0x96d6);h.pc=h.makepc(f.next);break;case S::CompareStatus:h.sub8(v[0].rl,3);break;case S::RestoreForClear:case S::RestoreForRefresh:case S::RestoreAddress:restore(v[4].r);break;case S::ClearValue:v[1].er=h.sub32(v[1].er,v[1].er);break;case S::RestoreIndexForRefresh:case S::RestoreIndex:case S::RestoreCurrent:restore(v[0].r);break;case S::ReadBase:f.move(v[0].rh,t.base());break;case S::ResolvePart:v[0].rl=h.add8(v[0].rl,v[0].rh);break;case S::NextAddress:f.inc(v[4].r,1);break;case S::NextIndex:f.inc(v[0].rl,1);break;case S::CountDown:f.inc(v[0].rh,-1);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::DispatchStatus&&stage!=S::DispatchClear&&stage!=S::DispatchGlobal&&stage!=S::Finish)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Part refresh clocks differ");return true;}}

